/* Animated Backgrounds — service worker (generated by scripts/build.mjs) */
const VERSION = 'preview-sidebar-20261126-v2';
const CORE = `ab-core-${VERSION}`;
const PAGES = 'ab-pages';
const IMGS = 'ab-thumbs';
const CDN = 'ab-cdn';
const PRECACHE = [
  '/', '/offline.html', '/manifest.webmanifest',
  `/assets/css/site.css?v=${VERSION}`, `/assets/css/app.css?v=${VERSION}`,
  `/assets/js/app.js?v=${VERSION}`, `/assets/js/monetize.js?v=${VERSION}`, `/assets/js/monetize.config.js?v=${VERSION}`,
  '/data/backgrounds.json', '/assets/icons/android-chrome-192x192.png', '/assets/icons/android-chrome-512x512.png'
];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CORE).then(c => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k.startsWith('ab-core-') && k !== CORE).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});

async function trim(name, max) {
  const c = await caches.open(name); const keys = await c.keys();
  for (let i = 0; i < keys.length - max; i++) await c.delete(keys[i]);
}
async function networkFirst(req, cacheName, fallback) {
  const c = await caches.open(cacheName);
  try {
    const res = await fetch(req);
    if (res && res.ok) c.put(req, res.clone());
    return res;
  } catch (e) {
    return (await c.match(req)) || (await caches.match(req, { ignoreSearch: true })) || (fallback && (await caches.match(fallback)));
  }
}
async function staleWhileRevalidate(req, cacheName, max) {
  const c = await caches.open(cacheName);
  const hit = await c.match(req);
  const net = fetch(req).then(res => {
    if (res && (res.ok || res.type === 'opaque')) { c.put(req, res.clone()); if (max) trim(cacheName, max); }
    return res;
  }).catch(() => hit);
  return hit || net;
}

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);

  // never cache counters / analytics / ads / embeds / monetization SDKs
  if (/abacus\.jasoncameron\.dev|google-analytics|googletagmanager|googlesyndication|doubleclick|codepen\.io\/.+\/embed|zerogpu/.test(url.href)) return;

  if (url.origin === location.origin) {
    // Always check the current app code with the network first. Otherwise a
    // long-lived service-worker cache can keep an old counter implementation.
    if (url.pathname === '/assets/js/app.js' || url.pathname === '/assets/css/app.css') { e.respondWith(networkFirst(req, CORE)); return; }
    if (req.mode === 'navigate') { e.respondWith(networkFirst(req, PAGES, '/offline.html')); return; }
    if (url.pathname === '/data/backgrounds.json' || url.pathname === '/data/stats.json' || url.pathname === '/data/blog.json' || url.pathname === '/data/meta.json') { e.respondWith(networkFirst(req, PAGES)); return; }
    if (url.pathname.startsWith('/assets/shots/')) { e.respondWith(staleWhileRevalidate(req, IMGS, 600)); return; }
    e.respondWith(caches.match(req).then(r => r || staleWhileRevalidate(req, CORE)));
    return;
  }
  if (url.hostname === 'shots.codepen.io' || url.hostname === 'assets.codepen.io') { e.respondWith(staleWhileRevalidate(req, IMGS, 400)); return; }
  if (/fonts\.(googleapis|gstatic)\.com|cdn\.jsdelivr\.net/.test(url.hostname)) { e.respondWith(staleWhileRevalidate(req, CDN, 60)); return; }
});
